24	// the caller provides a context without a deadline.
25	var defaultRunTimeout = 30 * time.Second //nolint:gochecknoglobals // overridable for testing
26	
27	// Agent implements agent.Agent by delegating to an external binary.
28	// Each method invokes a subcommand on the binary and parses the JSON response.
29	type Agent struct {
30		binaryPath string
31		info       *InfoResponse
32	}
33	
34	// New creates an Agent by calling the binary's "info" subcommand
35	// to cache its metadata. Returns an error if the binary cannot be invoked or returns
36	// invalid/incompatible protocol data. The provided context bounds the "info" call;
37	// pass a context with a deadline to limit how long discovery waits for each binary.
38	func New(ctx context.Context, binaryPath string) (*Agent, error) {
39		ea := &Agent{binaryPath: binaryPath}
40	
41		stdout, err := ea.run(ctx, nil, "info")
42		if err != nil {
43			return nil, fmt.Errorf("info: %w", err)
44		}
45	
46		var info InfoResponse
47		if err := json.Unmarshal(stdout, &info); err != nil {
48			return nil, fmt.Errorf("info: invalid JSON: %w", err)
49		}
50	
51		if info.ProtocolVersion != ProtocolVersion {
52			return nil, fmt.Errorf("protocol version mismatch: binary reports %d, expected %d",
53				info.ProtocolVersion, ProtocolVersion)
54		}
55	
56		ea.info = &info
57		return ea, nil
58	}
59	
